            schedule.LastFailedUtc = timestamp;
            schedule.LastRunUtc = timestamp;
            schedule.LastRunAtUtc = timestamp;
            schedule.NextRunUtc = CalculateNextRunUtc(schedule.CronExpression, nowUtc);
            schedule.LastError = normalizedError;
