            var index = schedules.FindIndex(item => item.Id.Equals(id, StringComparison.OrdinalIgnoreCase));
            if (index < 0)
            {
                return null;
            }

            schedules[index].Enabled = enabled;
            await SaveAsync(schedules, cancellationToken);
