            }

            var timestamp = nowUtc.UtcDateTime;
            schedule.IsRunning = false;
            schedule.LastCompletedUtc = timestamp;
            schedule.LastRunUtc = timestamp;
            schedule.LastRunAtUtc = timestamp;
            schedule.LastError = null;
