```csharp
using System.Text.Json;
using AiBox.DevPortal.Models;

namespace AiBox.DevPortal.Services;

public sealed class ScheduledAgentRunService(
    IWebHostEnvironment environment,
    ExecutionPolicyProfileService executionPolicyProfileService)
{
    private const string ExecutionsFileName = "scheduled-agent-executions.json";

    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web)
    {
        WriteIndented = true
    };

    private static readonly SemaphoreSlim FileLock = new(1, 1);

    public async Task<IReadOnlyList<ScheduledAgentExecution>> GetExecutionsAsync(CancellationToken cancellationToken = default)
    {
        await FileLock.WaitAsync(cancellationToken);
        try
        {
            return (await LoadExecutionsAsync(cancellationToken))
                .OrderBy(item => item.StartedUtc, DateTimeOffsetComparer.Default)
                .Select(Clone)
                .ToArray();
        }
        finally
        {
            FileLock.Release();
        }
    }

    public async Task<IReadOnlyList<ScheduledAgentExecution>> GetExecutionsForRunAsync(string runId, CancellationToken cancellationToken = default)
    {
        await FileLock.WaitAsync(cancellationToken);
        try
        {
            return (await LoadExecutionsAsync(cancellationToken))
                .Where(item => item.ScheduledRunId.Equals(runId, StringComparison.OrdinalIgnoreCase))
                .OrderBy(item => item.StartedUtc, DateTimeOffsetComparer.Default)
                .Select(Clone)
                .ToArray();
        }
        finally
        {
            FileLock.Release();
        }
    }

    private async Task<List<ScheduledAgentExecution>> LoadExecutionsAsync(CancellationToken cancellationToken)
    {
        var path = GetExecutionsPath();
        if (!File.Exists(path))
        {
            return [];
        }

        await using var stream = File.OpenRead(path);
        return await JsonSerializer.DeserializeAsync<List<ScheduledAgentExecution>>(stream, JsonOptions, cancellationToken) ?? [];
    }

    private string GetExecutionsPath()
    {
        return Path.Combine(environment.ContentRootPath, "Data", ExecutionsFileName);
    }

    private ScheduledAgentExecution Clone(ScheduledAgentExecution execution)
    {
        // Ensure a deep copy to avoid mutating the original object
        return JsonSerializer.Deserialize<ScheduledAgentExecution>(JsonSerializer.Serialize(execution), JsonOptions)!;
    }
}
