using System.Text.Json;
using AiBox.DevPortal.Models;

namespace AiBox.DevPortal.Services;

public sealed class ScheduledAgentRunService(
    IWebHostEnvironment environment,
    ExecutionPolicyProfileService executionPolicyProfileService)
{
    private const string ExecutionsFileName = "scheduled-agent-executions.json";

    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web)
    {
        WriteIndented = true
    };

    private static readonly SemaphoreSlim FileLock = new(1, 1);

    public async Task<IReadOnlyList<ScheduledAgentExecution>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        await FileLock.WaitAsync(cancellationToken);
        try
        {
            return (await LoadAsync(cancellationToken))
                .OrderBy(item => item.Id, StringComparer.OrdinalIgnoreCase)
                .Select(Clone)
                .ToArray();
        }
        finally
        {
            FileLock.Release();
        }
    }

    public async Task<ScheduledAgentExecution> CreateExecutionAsync(ScheduledAgentExecution execution, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(execution);

        var saved = await ValidateAndNormalizeAsync(execution, cancellationToken);
        saved.Id = Guid.NewGuid().ToString("N");
        saved.StartedUtc = saved.StartedUtc == default ? DateTime.UtcNow : saved.StartedUtc;

        await FileLock.WaitAsync(cancellationToken);
        try
        {
            var executions = await LoadAsync(cancellationToken);
            executions.Add(saved);
            await SaveAsync(executions, cancellationToken);
            return Clone(saved);
        }
        finally
        {
            FileLock.Release();
        }
    }

    public async Task<IEnumerable<ScheduledAgentExecution>> GetExecutionsForRunAsync(string runId, CancellationToken cancellationToken = default)
    {
        await FileLock.WaitAsync(cancellationToken);
        try
        {
            var executions = await LoadAsync(cancellationToken);
            return executions
                .Where(item => item.ScheduledRunId == runId)
                .OrderBy(item => item.Id, StringComparer.OrdinalIgnoreCase)
                .Select(Clone)
                .ToArray();
        }
        finally
        {
            FileLock.Release();
        }
    }

    public async Task<ScheduledAgentExecution> MarkExecutionCompletedAsync(string executionId, CancellationToken cancellationToken = default)
    {
        await FileLock.WaitAsync(cancellationToken);
        try
        {
            var executions = await LoadAsync(cancellationToken);
            var execution = executions.FirstOrDefault(item => item.Id.Equals(executionId, StringComparison.OrdinalIgnoreCase));
            if (execution is null)
            {
                return null;
            }

            execution.CompletedUtc = DateTime.UtcNow;
            execution.Success = true;
            execution.Error = null;

            await SaveAsync(executions, cancellationToken);
            return Clone(execution);
        }
        finally
        {
            FileLock.Release();
        }
    }

    public async Task<ScheduledAgentExecution> MarkExecutionFailedAsync(string executionId, string error, CancellationToken cancellationToken = default)
    {
        await FileLock.WaitAsync(cancellationToken);
        try
        {
            var executions = await LoadAsync(cancellationToken);
            var execution = executions.FirstOrDefault(item => item.Id.Equals(executionId, StringComparison.OrdinalIgnoreCase));
            if (execution is null)
            {
                return null;
            }

            execution.CompletedUtc = DateTime.UtcNow;
            execution.Success = false;
            execution.Error = error;

            await SaveAsync(executions, cancellationToken);
            return Clone(execution);
        }
        finally
        {
            FileLock.Release();
        }
    }

    private async Task<List<ScheduledAgentExecution>> LoadAsync(CancellationToken cancellationToken)
    {
        var path = GetExecutionsPath();
        if (!File.Exists(path))
        {
            return [];
        }

        await using var stream = File.OpenRead(path);
        return await JsonSerializer.DeserializeAsync<List<ScheduledAgentExecution>>(stream, JsonOptions, cancellationToken) ?? [];
    }

    private async Task SaveAsync(List<ScheduledAgentExecution> executions, CancellationToken cancellationToken)
    {
        var path = GetExecutionsPath();
        var directory = Path.GetDirectoryName(path);
        if (!string.IsNullOrWhiteSpace(directory))
        {
            Directory.CreateDirectory(directory);
        }

        await using var stream = File.Create(path);
        await JsonSerializer.SerializeAsync(stream, executions, JsonOptions, cancellationToken);
    }

    private string GetExecutionsPath()
    {
        return Path.Combine(environment.ContentRootPath, "Data", ExecutionsFileName);
    }

    private async Task<ScheduledAgentExecution> ValidateAndNormalizeAsync(ScheduledAgentExecution execution, CancellationToken cancellationToken)
    {
        var scheduledRunId = execution.ScheduledRunId?.Trim();
        if (string.IsNullOrWhiteSpace(scheduledRunId))
        {
            throw new ArgumentException("Scheduled run ID is required.");
        }

        return execution;
    }

