    private async Task SaveExecutionRecordsAsync(List<ExecutionRecord> records, CancellationToken cancellationToken)
    {
        var path = GetExecutionRecordsPath();
        var directory = Path.GetDirectoryName(path);
        if (!string.IsNullOrWhiteSpace(directory))
        {
            Directory.CreateDirectory(directory);
        }

        await using var stream = File.Create(path);
        await JsonSerializer.SerializeAsync(stream, records, JsonOptions, cancellationToken);
    }

    private string GetExecutionRecordsPath()
    {
        return Path.Combine(environment.ContentRootPath, "Data", ExecutionRecordsFileName);
    }
