    {
        if (string.IsNullOrWhiteSpace(id))
        {
            return null;
        }

        var execution = await LoadExecutionsAsync(cancellationToken).ConfigureAwait(false);
        return execution.FirstOrDefault(item => item.Id.Equals(id, StringComparison.OrdinalIgnoreCase));
    }

    public async Task<ScheduledAgentExecution> CreateExecutionAsync(ScheduledAgentExecution execution, CancellationToken cancellationToken = default)
    {
        execution.Id = Guid.NewGuid().ToString("N");
        execution.CreatedAtUtc = DateTime.UtcNow;

        _executions.Add(execution);
        await SaveExecutionsAsync(cancellationToken).ConfigureAwait(false);

        return Clone(execution);
    }

    public async Task<IReadOnlyList<ScheduledAgentExecution>> GetExecutionsAsync(CancellationToken cancellationToken = default)
    {
