        return executions.Where(item => item.ScheduledRunId.Equals(scheduledRunId, StringComparison.OrdinalIgnoreCase)).Select(Clone).ToArray();
    }

    // Private helpers
    private async Task<List<ScheduledAgentExecution>> LoadExecutionsAsync(CancellationToken cancellationToken = default)
