   public static IReadOnlyList<string> ExtractRequestedCreateFiles(string task)
   {
       var value = task ?? string.Empty;
       if (string.IsNullOrWhiteSpace(value))
       {
           return [];
       }

       var normalized = value.Replace("\r\n", "\n", StringComparison.Ordinal).Replace('\r', '\n');
       var createdFiles = new List<string>();
       var inCreateSection = false;

       foreach (var line in normalized.Split('\n'))
       {
           if (line.TrimStart().Equals("Create:", StringComparison.OrdinalIgnoreCase))
           {
               inCreateSection = true;
               continue;
           }

           if (!inCreateSection)
           {
               continue;
           }

           var trimmedLine = line.Trim();
           if (string.IsNullOrEmpty(trimmedLine))
           {
               continue;
           }

           // Ignore version labels like "V2.6"
           if (trimmedLine.Contains("V", StringComparison.OrdinalIgnoreCase))
           {
               continue;
           }

           createdFiles.Add(trimmedLine);
       }

       return createdFiles;
   }
