public static IReadOnlyList<string> ExtractRequestedCreateFiles(string task)
{
    var value = task ?? string.Empty;
    if (string.IsNullOrWhiteSpace(value))
    {
        return [];
    }

    var normalized = value.Replace("\r\n", "\n", StringComparison.Ordinal).Replace('\r', '\n');
    var createdFiles = new List<string>();
    var inCreateSection = false;

    foreach (var line in normalized.Split('\n'))
    {
        var trimmed = line.Trim();
        if (string.IsNullOrWhiteSpace(trimmed))
        {
            inCreateSection = false;
            continue;
        }

        if (TryConsumeCreateHeader(trimmed, out var remainder))
        {
            inCreateSection = true;
            AddCreatePaths(createdFiles, remainder);
            continue;
        }

        if (!inCreateSection)
        {
            continue;
        }

        // Ignore version labels
        if (trimmed.Contains("V"))
        {
            continue;
        }

        AddCreatePaths(createdFiles, trimmed);
    }

    return createdFiles
        .Distinct(StringComparer.OrdinalIgnoreCase)
        .ToArray();
}

private static void AddCreatePaths(List<string> createdFiles, string remainder)
{
    foreach (var path in remainder.Split(','))
    {
        var fullPath = path.Trim();
        if (!string.IsNullOrWhiteSpace(fullPath) && fullPath.EndsWith(".cs") || fullPath.EndsWith(".razor"))
        {
            createdFiles.Add(fullPath);
        }
    }
}
