public class PatchIntentService : IPatchIntentService
{
    public List<string> ExtractTargetCreatedFiles(string userRequest)
    {
        // Regex pattern to match .cs and .razor files, ignoring version labels like "V2.6"
        var filePattern = @"\b[^\s]+\.(?:cs|razor)\b(?<!V\d+\.\d+)";

        // Extract file paths using the regex pattern
        var matches = Regex.Matches(userRequest, filePattern);

        // Convert matches to a list of strings
        return matches.Cast<Match>().Select(m => m.Value).ToList();
    }
}
