using AiBox.DevPortal.Models;
using AiBox.DevPortal.Services.Agents;

namespace AiBox.DevPortal.Services;

public class AgentDashboardMetricsService : IAgentDashboardMetricsService
{
    private readonly ITaskSliceExecutionService _taskSliceExecutionService;
    private readonly IProjectHistoryIndexService _projectHistoryIndexService;
    private readonly IPatchApprovalGateService _patchApprovalGateService;

    public AgentDashboardMetricsService(
        ITaskSliceExecutionService taskSliceExecutionService,
        IProjectHistoryIndexService projectHistoryIndexService,
        IPatchApprovalGateService patchApprovalGateService)
    {
        _taskSliceExecutionService = taskSliceExecutionService;
        _projectHistoryIndexService = projectHistoryIndexService;
        _patchApprovalGateService = patchApprovalGateService;
    }

    public async Task<AgentDashboardMetrics> GetMetricsAsync()
    {
        var metrics = new AgentDashboardMetrics();

        // Aggregate metrics from relevant services
        var executionResults = await _taskSliceExecutionService.GetAllAsync();
        var projectHistory = await _projectHistoryIndexService.LoadAsync();
        var completedFeatures = projectHistory.CompletedFeatures;
        var pendingFeatures = projectHistory.PendingFeatures;

        metrics.TotalPlans = executionResults.Count;
        metrics.TotalSlices = executionResults.Select(r => r.SliceId).Distinct().Count();
        metrics.TotalGeneratePatch = executionResults.Count(r => !string.IsNullOrEmpty(r.PatchPackageId));
        metrics.TotalVerify = executionResults.Count(r => r.VerificationSuccess);
        metrics.TotalApply = executionResults.Count(r => r.Success && r.BuildSuccess);
        metrics.TotalRollback = executionResults.Count(r => !r.Success);

        metrics.PatchSuccessRate = (double)metrics.TotalApply / metrics.TotalGeneratePatch * 100;
        metrics.VerificationSuccessRate = (double)metrics.TotalVerify / metrics.TotalSlices * 100;
        metrics.ApplySuccessRate = (double)metrics.TotalApply / metrics.TotalPlans * 100;
        metrics.RollbackSuccessRate = (double)metrics.TotalRollback / metrics.TotalPlans * 100;

        metrics.CompletedFeaturesCount = completedFeatures.Count;
        metrics.PendingFeaturesCount = pendingFeatures.Count;
        metrics.RecommendedNextSlicesCount = projectHistory.RecommendedNextSlices.Count;

        // Additional logic to calculate failure reasons and build metrics

        return metrics;
    }
}
