                routedRequest.Task,
                prompt,
                result.Plan,
                success: true,
                errorMessage: string.Empty);
            return result;
        }
        catch (Exception exception)
        {
            await RecordAsync(
                AgentActionProfiles.CreatePlanActionKey,
                profile,
                routedRequest.Task,
                prompt,
                string.Empty,
                success: false,
                errorMessage: exception.Message);
            throw;
        }
    }

