            IsXmlDocumentationRequest(routedRequest.Task),
            targetResolution,
            repairContext,
            profile,
            BuildAgentInstructionsText(agentInstructionContext));

        try
        {
            var result = await coderConsoleService.GeneratePatchPreviewAsync(routedRequest, profile, repairContext);
            await RecordAsync(
