        await JsonSerializer.SerializeAsync(stream, profiles, JsonOptions, cancellationToken);
    }

    private string GetRegistryPath()
    {
        return Path.Combine(environment.ContentRootPath, "Data", "agent-mode-profiles.json");
    }

