        ".gif", ".gz", ".ico", ".jar", ".jpeg", ".jpg", ".mkv", ".mov", ".mp3", ".mp4",
        ".pdf", ".png", ".ppt", ".pptx", ".rar", ".so", ".svg", ".tar", ".tiff", ".wav",
