```csharp
using System;
using System.Collections.Generic;
using AiBox.DevPortal.Models;

namespace AiBox.DevPortal.Services
{
    public sealed class TaskDecompositionService
    {
        public TaskPlan BuildPlan(string originalRequest)
        {
            if (string.IsNullOrWhiteSpace(originalRequest))
                throw new ArgumentException("Original request cannot be null or whitespace.");

            var plan = new TaskPlan
            {
                OriginalRequest = originalRequest,
                Slices = new List<TaskSlice>(),
                CreatedAtUtc = DateTime.UtcNow
            };

            if (originalRequest.Length <= 1024) // Small request criteria
            {
                plan.Slices.Add(new TaskSlice
                {
                    Title = "Single Slice",
                    Goal = "Process the request as a single slice",
                    TargetFiles = new List<string> { "*.*" },
                    InstructionFiles = new List<string> { "AGENTS.md" },
                    AllowedChangeType = "Any",
                    MustNotChange = "",
                    VerificationCommands = new List<string> { "dotnet build" }
                });
            }
            else
            {
                var slices = DecomposeRequest(originalRequest);
                foreach (var slice in slices)
                {
                    plan.Slices.Add(slice);
                }
            }

            return plan;
        }

        private List<TaskSlice> DecomposeRequest(string request)
        {
            // Simple decomposition logic for demonstration purposes
            var slices = new List<TaskSlice>();
            int chunkSize = 1024;

            for (int i = 0; i < request.Length; i += chunkSize)
            {
                slices.Add(new TaskSlice
                {
                    Title = $"Slice {i / chunkSize + 1}",
                    Goal = "Process a chunk of the request",
                    TargetFiles = new List<string> { "*.*" },
                    InstructionFiles = new List<string> { "AGENTS.md" },
                    AllowedChangeType = "Any",
                    MustNotChange = "",
                    VerificationCommands = new List<string> { "dotnet build" }
                });
            }

            return slices;
        }
    }
}
