                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error reading file {file.RelativePath}: {ex.Message}");
                    continue;
                }

                _fileContentIndex[file.RelativePath] = new List<string>(content.Split(new[] { ' ', '.', ',', ';', ':', '\n' }, StringSplitOptions.RemoveEmptyEntries));
            }
        }

        public IEnumerable<string> SearchKnowledge(string query)
        {
            // Implement logic to search the indexed knowledge
