            foreach (var entry in _fileContentIndex)
            {
                if (entry.Value.Any(word => word.Contains(query, StringComparison.OrdinalIgnoreCase)))
                {
                    results.Add(entry.Key);
                }
            }

            return results;
        }
    }
}
