2. **Create Services/ProjectKnowledgeIndexService.cs**
   - Define a new service `ProjectKnowledgeIndexService` to handle operations related to `ProjectKnowledgeIndex`.
   ```csharp
   namespace AiBox.DevPortal.Services;

   using AiBox.DevPortal.Models;
   using System.Collections.Generic;
   using System.Threading.Tasks;

   public interface IProjectKnowledgeIndexService
   {
       Task<List<ProjectKnowledgeIndex>> GetAllAsync();
       Task AddAsync(ProjectKnowledgeIndex projectKnowledgeIndex);
       Task UpdateAsync(ProjectKnowledgeIndex projectKnowledgeIndex);
       Task DeleteAsync(int id);
   }

   public class ProjectKnowledgeIndexService : IProjectKnowledgeIndexService
   {
       private List<ProjectKnowledgeIndex> _projectKnowledgeIndices = new();

       public async Task<List<ProjectKnowledgeIndex>> GetAllAsync()
       {
           return await Task.FromResult(_projectKnowledgeIndices);
       }

       public async Task AddAsync(ProjectKnowledgeIndex projectKnowledgeIndex)
       {
           projectKnowledgeIndex.Id = _projectKnowledgeIndices.Count + 1;
           projectKnowledgeIndex.LastUpdated = DateTime.Now;
           _projectKnowledgeIndices.Add(projectKnowledgeIndex);
           await Task.CompletedTask;
       }

       public async Task UpdateAsync(ProjectKnowledgeIndex projectKnowledgeIndex)
       {
           var index = _projectKnowledgeIndices.FindIndex(p => p.Id == projectKnowledgeIndex.Id);
           if (index != -1)
           {
               _projectKnowledgeIndices[index] = projectKnowledgeIndex;
               await Task.CompletedTask;
           }
       }

       public async Task DeleteAsync(int id)
       {
           _projectKnowledgeIndices.RemoveAll(p => p.Id == id);
           await Task.CompletedTask;
