public class ProjectKnowledgeIndex
{
    public string Id { get; set; } = Guid.NewGuid().ToString("N");

    public string ProjectName { get; set; } = string.Empty;

    public DateTimeOffset LastUpdated { get; set; } = DateTimeOffset.UtcNow;

