    public DateTimeOffset ExpiryDate { get; set; }
}
```

### 2. Create Services/ProjectKnowledgeIndexService.cs
Implement a service to manage the project knowledge index, including CRUD operations.

```csharp
namespace AiBox.DevPortal.Services;

public class ProjectKnowledgeIndexService
{
    private List<ProjectKnowledgeIndex> _projectIndexes = new();

    public async Task AddOrUpdateProjectKnowledgeIndex(ProjectKnowledgeIndex index)
    {
        var existingIndex = _projectIndexes.FirstOrDefault(i => i.Id == index.Id);
        if (existingIndex != null)
        {
            existingIndex.CopyPropertiesFrom(index);
        }
        else
        {
            _projectIndexes.Add(index);
        }
    }

    public async Task<ProjectKnowledgeIndex?> GetProjectKnowledgeIndexById(string id)
    {
        return _projectIndexes.FirstOrDefault(i => i.Id == id);
    }

    private void CopyPropertiesFrom(ProjectKnowledgeIndex source)
    {
        typeof(ProjectKnowledgeIndex).GetProperties().ToList()
            .ForEach(prop =>
            {
                var value = prop.GetValue(source, null);
                if (value != null && !prop.Name.Equals("Id"))
                    prop.SetValue(this, value, null);
            });
    }
}
```

### 3. Create Components/Coder/CoderKnowledgePanel.razor
Create a component to display and manage project knowledge index.

```razor
@page "/coder/knowledge-panel"
@inject ProjectKnowledgeIndexService KnowledgeIndexService

<h3>Project Knowledge Index</h3>

<button @onclick="AddNewIndex">Add New Index</button>

@if (projectIndexes == null || projectIndexes.Count == 0)
{
    <p>No project knowledge indices found.</p>
}
else
{
    <ul>
        @foreach (var index in projectIndexes)
        {
            <li>@index.ProjectName - Last Updated: @index.LastUpdated.ToString("yyyy-MM-dd HH:mm:ss")</li>
        }
    </ul>
}

@code {
    private List<ProjectKnowledgeIndex> projectIndexes;

    protected override async Task OnInitializedAsync()
    {
        projectIndexes = await KnowledgeIndexService.GetProjectKnowledgeIndices();
    }

    private void AddNewIndex()
    {
        var newIndex = new ProjectKnowledgeIndex
        {
            ProjectName = "New Project",
            LastUpdated = DateTimeOffset.UtcNow
        };
        _projectIndexes.Add(newIndex);
    }
}
```

