        private readonly string _filePath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "verification-profiles.json");

        public async Task<List<VerificationProfile>> GetAllProfilesAsync()
        {
            if (!File.Exists(_filePath))
                return new List<VerificationProfile>();

            var json = await File.ReadAllTextAsync(_filePath);
            return JsonSerializer.Deserialize<List<VerificationProfile>>(json) ?? new List<VerificationProfile>();
        }

        public async Task AddProfileAsync(VerificationProfile profile)
        {
            var profiles = await GetAllProfilesAsync();
            if (!profiles.Any(p => p.Name == profile.Name))
                profiles.Add(profile);

            await SaveProfilesAsync(profiles);
        }

        public async Task UpdateProfileAsync(VerificationProfile profile)
        {
            var profiles = await GetAllProfilesAsync();
            var index = profiles.FindIndex(p => p.Name == profile.Name);
            if (index != -1)
                profiles[index] = profile;

            await SaveProfilesAsync(profiles);
        }

        public async Task DeleteProfileAsync(string name)
